mapper.select:
SELECT *
FROM
(
SELECT info.cash_id cashId,
fpt.finprod_abbr finprodAbbr,
info.finprod_id finprodId,
info.finprod_type finprodType,
info.cash_type_1 cashType1,
info.cash_type_1 cashType1Code,
info.cash_type_2 cashType2,
info.cash_type_2 cashType2Code,
DATE_FORMAT(ffcr.f_accr_date, '%Y-%m-%d') effDate,
crule.calc_type calcType,
crule.calc_type calcTypeCode,
crule.yield * 100 yield,
crule.basis,
crule.base_type baseType,
crule.base_type baseTypeCode,
crule.base_date_type baseDateType,
crule.base_date_type baseDateTypeCode,
prule.pay_cycle payCycle,
prule.pay_cycle payCycleCode,
prule.END_TDAY_RULE endTdayRule,
prule.END_TDAY_RULE endTdayRuleCode,
prule.PAY_TDAY_RULE payTdayRule,
prule.PAY_TDAY_RULE payTdayRuleCode,
prule.calc_rule calcRule,
prule.calc_rule calcRuleCode,
DATE_FORMAT(prule.first_pay_date, '%Y-%m-%d') firstPayDate,
prule.cash_unit_type cashUnitType,
prule.cash_unit_type cashUnitTypeCode,
prule.pay_type payType,
prule.pay_type payTypeCode,
crule.remark,
A.ACCR_TDAY_RULE as accrTdayRule,
rn1,
rn2
FROM FIN_CASH_INFO info
LEFT JOIN fin_product fpt
ON info.finprod_id = fpt.finprod_id
LEFT JOIN (
/* 子查询必加上rn字段 */
SELECT result.* FROM (
SELECT tmp.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@CASH_ID = tmp.CASH_ID and
@FINPROD_ID = tmp.FINPROD_ID and
@FINPROD_TYPE = tmp.FINPROD_TYPE

),
@rank := @rank + 1,
@rank := 1
) AS rn1, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@CASH_ID := tmp.CASH_ID /* 分组条件1 */
, @FINPROD_ID := tmp.FINPROD_ID /* 分组条件2 */
, @FINPROD_TYPE := tmp.FINPROD_TYPE /* 分组条件3 */

FROM (
/* 数据源 */
SELECT bc.*
FROM fin_cash_calc_rule bc
ORDER BY CAST(bc.EFF_DATE as SIGNED) DESC /* 按实际情况与oracle保持一至的排序 */
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@CASH_ID := null,
@FINPROD_ID = null,
@FINPROD_TYPE = null,
@rank := 0) a
) result
) crule
ON info.cash_id = crule.cash_id
AND info.finprod_id = crule.finprod_id
AND info.finprod_type = crule.finprod_type
LEFT JOIN (
/* 子查询必加上rn字段 */
SELECT result.* FROM (
SELECT tmp.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@CASH_ID = tmp.CASH_ID and
@FINPROD_ID = tmp.FINPROD_ID and
@FINPROD_TYPE = tmp.FINPROD_TYPE
),
@rank := @rank + 1,
@rank := 1
) AS rn2, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@CASH_ID := tmp.CASH_ID /* 分组条件1 */
, @FINPROD_ID := tmp.FINPROD_ID /* 分组条件2 */
, @FINPROD_TYPE := tmp.FINPROD_TYPE /* 分组条件3 */
FROM (
/* 数据源 */
SELECT bc.*
FROM fin_cash_pay_rule bc left join fin_cash_calc_rule fr
on bc.CASH_ID = fr.CASH_ID
ORDER BY CAST(fr.EFF_DATE as SIGNED) DESC /* 按实际情况与oracle保持一至的排序 */
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@CASH_ID := null,
@FINPROD_ID = null,
@FINPROD_TYPE = null,
@rank := 0) a
) result
) prule
ON info.cash_id = prule.cash_id
AND info.finprod_id = prule.finprod_id
AND info.finprod_type = prule.finprod_type
LEFT JOIN Fin_Float_Counting_Rule ffcr
ON crule.cash_id = ffcr.cash_id
AND crule.eff_date = ffcr.eff_date
LEFT JOIN  (
SELECT
CASH_ID,
ACCR_TDAY_RULE
from FIN_FLOAT_COUNTING_RULE
GROUP BY
CASH_ID,
ACCR_TDAY_RULE
) A
ON A.CASH_ID = info.CASH_ID
WHERE info.cash_type_1 = '03'

	AND info.FINPROD_id = #{finprodId}


	AND info.cash_type_2 = #{cashType2}


	AND info.cash_type_2 != #{noCashType2}

)
WHERE
rn1 = 1
AND rn2 = 1

select ffcr2.ACT_RULE actRule, ffcr2.base_type baseType, ffcr2.AST_VDATE_TYPE actVdateType, DATE_FORMAT(ffcr.f_accr_date, '%Y-%m-%d') firCalculaDate, DATE_FORMAT(ffcr.e_accr_date, '%Y-%m-%d') endCalculaDate, ffcr.ACCR_CYCLE_UNIT accrCycle from fin_cash_info fci left join fin_float_counting_rule ffcr on fci.cash_id = ffcr.cash_id left join fin_float_calc_rule ffcr2 on ffcr2.cash_id = ffcr.cash_id where 1=1
AND fci.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}

select DATE_FORMAT(ffas.accr_str_date, '%Y-%m-%d') jtStrDate, DATE_FORMAT(ffas.accr_end_date, '%Y-%m-%d') jtEndDate, DATE_FORMAT(ffas.accr_date, '%Y-%m-%d') jtDate from fin_cash_info fci LEFT JOIN FIN_FLOAT_ACCRUAL_SCHE ffas ON ffas.cash_id = fci.cash_id where 1=1
AND fci.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}
order by ffas.accr_str_date asc

select ffas.cash_id as cashId, ffas.accr_date as jtDate
    from Fin_Float_Accrual_Sche ffas
where ffas.cash_id = #{cashId}
    and DATE_FORMAT(ffas.accr_date, '%Y-%m-%d') = #{jtDate}

select fccr.cash_id as cashId
    from FIN_CASH_CALC_RULE fccr
where fccr.cash_id = #{cashId}
and DATE_FORMAT(fccr.eff_date, '%Y-%m-%d') = #{effDate}
